--
-- Name: canopy_demo_heartbeat(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canopy_demo_heartbeat(unit_keys text[]) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  UPDATE sync_leaf_node leaf SET last_seen_at = now()
  FROM canopy_leaf_unit unit
  WHERE unit.leaf_id = leaf.leaf_id AND unit.is_demo AND unit.unit_key = ANY(unit_keys)
    AND leaf.leaf_id LIKE 'demo-%' AND leaf.last_seen_at < now() - interval '15 seconds';
  UPDATE sync_case_index c SET last_synced_at = now()
  FROM canopy_leaf_unit unit
  WHERE unit.leaf_id = c.leaf_id AND unit.is_demo AND unit.unit_key = ANY(unit_keys)
    AND c.leaf_id LIKE 'demo-%' AND upper(c.status) = 'ACTIVE'
    AND c.last_synced_at < now() - interval '15 seconds';
$$;


--
-- Name: canopy_demo_reset(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canopy_demo_reset() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  demo_locations bigint[];
  demo_keys text[];
  removed_cases integer;
  removed_leaves integer;
  removed_archive integer;
BEGIN
  WITH RECURSIVE tree AS (
    SELECT id FROM canopy_location WHERE is_demo
    UNION SELECT child.id FROM canopy_location child JOIN tree ON child.parent_id = tree.id
  ) SELECT coalesce(array_agg(id), '{}') INTO demo_locations FROM tree;
  SELECT coalesce(array_agg(id::text), '{}') INTO demo_keys
  FROM canopy_location WHERE is_demo AND kind = 'care_unit';

  DELETE FROM sync_case_index WHERE leaf_id LIKE 'demo-%';
  GET DIAGNOSTICS removed_cases = ROW_COUNT;
  DELETE FROM sync_message WHERE leaf_id LIKE 'demo-%';
  DELETE FROM canopy_leaf_assignment
  WHERE leaf_id LIKE 'demo-%' OR bed_location_id = ANY(demo_locations);
  DELETE FROM sync_leaf_node WHERE leaf_id LIKE 'demo-%';
  GET DIAGNOSTICS removed_leaves = ROW_COUNT;
  DELETE FROM archive_case WHERE source_system = 'flora-demo';
  GET DIAGNOSTICS removed_archive = ROW_COUNT;
  DELETE FROM auth_user_unit WHERE unit_key = ANY(demo_keys);
  -- Children first: canopy_location.parent_id is ON DELETE RESTRICT.
  DELETE FROM canopy_location WHERE id = ANY(demo_locations) AND kind = 'bed';
  DELETE FROM canopy_location WHERE id = ANY(demo_locations) AND kind = 'room';
  DELETE FROM canopy_location WHERE id = ANY(demo_locations);
  RETURN jsonb_build_object('cases', removed_cases, 'leaves', removed_leaves,
                            'archive_cases', removed_archive, 'locations', cardinality(demo_locations));
END $$;


--
-- Name: flora_log_case_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flora_log_case_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  change_set text := nullif(current_setting('flora.change_set', true), '');
  old_row jsonb;
  new_row jsonb;
  row_case bigint;
BEGIN
  IF change_set IS NULL THEN RETURN NULL; END IF;
  IF TG_OP <> 'INSERT' THEN old_row := to_jsonb(OLD); END IF;
  IF TG_OP <> 'DELETE' THEN new_row := to_jsonb(NEW); END IF;
  IF TG_OP = 'UPDATE' AND old_row = new_row THEN RETURN NULL; END IF;
  row_case := coalesce((new_row->>'case_id')::bigint, (old_row->>'case_id')::bigint);
  IF row_case IS NULL AND TG_TABLE_NAME = 'case_io_segment' THEN
    SELECT case_id INTO row_case FROM case_io_run
     WHERE id = coalesce((new_row->>'run_id')::bigint, (old_row->>'run_id')::bigint);
  END IF;
  VALUES (change_set, row_case, TG_TABLE_NAME, coalesce((new_row->>'id')::bigint, (old_row->>'id')::bigint),
          TG_OP, old_row, new_row, nullif(current_setting('flora.actor', true), ''),
          (extract(epoch FROM clock_timestamp()) * 1000)::bigint);
  RETURN NULL;
END $$;


--
-- Name: formdev_guard_published_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.formdev_guard_published_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status IN ('published','archived') THEN
    IF TG_OP = 'DELETE' OR NEW.definition IS DISTINCT FROM OLD.definition
       OR NEW.checksum IS DISTINCT FROM OLD.checksum OR NEW.status = 'draft' THEN
      RAISE EXCEPTION 'published form versions are immutable' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: ai_service_config; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ai_service_config (
    id bigint DEFAULT 1 NOT NULL,
    api_format text DEFAULT 'anthropic'::text NOT NULL,
    host text DEFAULT ''::text NOT NULL,
    api_key text DEFAULT ''::text NOT NULL,
    model text DEFAULT ''::text NOT NULL,
    version bigint DEFAULT 0 NOT NULL,
    updated_at bigint DEFAULT 0 NOT NULL,
    updated_by text,
    CONSTRAINT ai_service_config_api_format_check CHECK ((api_format = ANY (ARRAY['anthropic'::text, 'openai'::text]))),
    CONSTRAINT ai_service_config_id_check CHECK ((id = 1))
);


