    owner_user_id bigint NOT NULL,
    session_id uuid,
    title text NOT NULL,
    html text NOT NULL,
    data jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at bigint NOT NULL,
    updated_at bigint NOT NULL,
    last_run_at bigint,
    shared boolean DEFAULT false NOT NULL
);


