    or_type_code text,
    is_demo boolean DEFAULT false NOT NULL,
    CONSTRAINT canopy_location_kind_check CHECK ((kind = ANY (ARRAY['hospital'::text, 'building'::text, 'care_unit'::text, 'room'::text, 'bed'::text]))),
    CONSTRAINT canopy_location_room_type_check CHECK (((room_type IS NULL) OR (room_type = ANY (ARRAY['or'::text, 'recovery'::text, 'other'::text]))))
);


--
-- Name: canopy_leaf_unit; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.canopy_leaf_unit AS
 SELECT assignment.leaf_id,
    (unit.id)::text AS unit_key,
    unit.name AS unit_name,
    unit.is_demo
   FROM (((public.canopy_leaf_assignment assignment
     JOIN public.canopy_location bed ON ((bed.id = assignment.bed_location_id)))
     JOIN public.canopy_location room ON ((room.id = bed.parent_id)))
     JOIN public.canopy_location unit ON (((unit.id = room.parent_id) AND (unit.kind = 'care_unit'::text))));


